{"times.py": """"UTC instant normalization helpers for the synthetic snapshot pipeline."""

from datetime import datetime, timezone

__all__ = ["instant"]


def instant(value):
    """Return a timezone-aware UTC datetime for value.

    Accepts datetime objects and ISO8601 strings understood by
    datetime.fromisoformat, including the Z designator. The value must be
    timezone aware with a non-None UTC offset. Naive values, unparsable
    strings and non-string, non-datetime inputs raise ValueError.
    """
    if isinstance(value, datetime):
        parsed = value
    elif isinstance(value, str):
        try:
            parsed = datetime.fromisoformat(value)
        except (ValueError, TypeError, OverflowError):
            raise ValueError("unparsable ISO8601 instant: " + repr(value))
    else:
        raise ValueError("unsupported instant type: " + type(value).__name__)
    if parsed.tzinfo is None:
        raise ValueError("instant must be timezone aware: " + repr(value))
    offset = parsed.utcoffset()
    if offset is None:
        raise ValueError("instant must carry a UTC offset: " + repr(value))
    return parsed.astimezone(timezone.utc)", "quotes.py": """"Odds conversion and per-book quote selection."""

import math

import times

__all__ = ["probability", "select"]


def probability(value):
    """Convert American odds into an implied probability.

    Accepts finite int and float values plus float-convertible strings,
    with bool rejected. Unsupported types, conversion or overflow failures,
    NaN or infinite values and magnitudes below 100 raise ValueError.
    Positive odds use 100 / (v + 100) and negative odds use
    magnitude / (magnitude + 100).
    """
    if isinstance(value, bool):
        raise ValueError("bool odds are not supported")
    if isinstance(value, str):
        try:
            number = float(value)
        except (ValueError, TypeError, OverflowError):
            raise ValueError("odds are not float-convertible: " + repr(value))
    elif isinstance(value, (int, float)):
        try:
            number = float(value)
        except (ValueError, TypeError, OverflowError):
            raise ValueError("odds are not a finite float: " + repr(value))
    else:
        raise ValueError("unsupported odds type: " + type(value).__name__)
    if not math.isfinite(number):
        raise ValueError("odds must be finite: " + repr(value))
    if abs(number) < 100.0:
        raise ValueError("odds magnitude must be at least 100: " + repr(value))
    if number > 0.0:
        result = 100.0 / (number + 100.0)
    else:
        magnitude = -number
        result = magnitude / (magnitude + 100.0)
    if not math.isfinite(result):
        raise ValueError("odds do not map to a finite probability: " + repr(value))
    return float(result)


def select(rows, event, asof):
    """Select the best eligible quote per book for event at asof.

    Returns a dict keyed by book; each value maps row to the original input
    dict and probability to the implied probability. Malformed rows are
    skipped and neither the input lists nor any input dict is mutated. The
    greatest observed instant per book wins, ties use the lexicographically
    smallest id and exact id ties keep the first eligible input row.
    """
    as_of = times.instant(asof)
    if not isinstance(event, str) or len(event) == 0:
        raise ValueError("event must be a nonempty string")
    candidates = {}
    for row in _rows(rows):
        if not isinstance(row, dict):
            continue
        quote_id = row.get("id")
        book = row.get("book")
        row_event = row.get("event")
        if not isinstance(quote_id, str) or len(quote_id) == 0:
            continue
        if not isinstance(book, str) or len(book) == 0:
            continue
        if not isinstance(row_event, str) or row_event != event:
            continue
        try:
            observed = times.instant(row.get("observed_at"))
            expires = times.instant(row.get("expires_at"))
            updated = times.instant(row.get("last_update"))
        except ValueError:
            continue
        if not (observed <= as_of < expires):
            continue
        if updated > observed:
            continue
        try:
            odds = probability(row.get("odds"))
        except ValueError:
            continue
        current = candidates.get(book)
        if current is None:
            candidates[book] = (observed, quote_id, row, odds)
            continue
        if observed > current[0]:
            candidates[book] = (observed, quote_id, row, odds)
        elif observed == current[0] and quote_id < current[1]:
            candidates[book] = (observed, quote_id, row, odds)
    return {
        book: {"row": entry[2], "probability": entry[3]}
        for book, entry in candidates.items()
    }


