import times

__all__ = ["reconcile"]

_STATUSES = ("ok", "partial", "failed", "pending")


def reconcile(rows, asof):
    """Reconcile run rows into one latest-attempt record per job.

    Rows are validated and malformed or future rows are skipped. Eligible
    rows are first deduplicated by run_id keeping the greatest observed
    instant with first-input order on exact ties, then the best record per
    job is chosen by greatest attempt, greatest observed instant and finally
    the lexicographically smallest run_id. Original input dicts are returned
    unchanged and are never mutated.
    """
    as_of = times.instant(asof)
    by_run_id = {}
    for row in _rows(rows):
        if not isinstance(row, dict):
            continue
        run_id = row.get("run_id")
        job = row.get("job")
        if not isinstance(run_id, str) or len(run_id) == 0:
            continue
        if not isinstance(job, str) or len(job) == 0:
            continue
        attempt = row.get("attempt")
        if isinstance(attempt, bool) or not isinstance(attempt, int):
            continue
        if attempt <= 0:
            continue
        try:
            observed = times.instant(row.get("observed_at"))
        except ValueError:
            continue
        if observed > as_of:
            continue
        status = row.get("status")
        if not isinstance(status, str) or status not in _STATUSES:
            continue
        downloaded = row.get("downloaded_rows")
        if isinstance(downloaded, bool) or not isinstance(downloaded, int):
            continue
        if downloaded < 0:
            continue
        if status in ("failed", "pending") and downloaded != 0:
            continue
        current = by_run_id.get(run_id)
        if current is None or observed > current[0]:
            by_run_id[run_id] = (observed, row)
    best = {}
    for run_id, (observed, row) in by_run_id.items():
        job = row["job"]
        attempt = row["attempt"]
        current = best.get(job)
        if current is None:
            best[job] = (attempt, observed, run_id, row)
            continue
        cur_attempt = current[0]
        cur_observed = current[1]
        cur_run_id = current[2]
        replace = False
        if attempt > cur_attempt:
            replace = True
        elif attempt == cur_attempt:
            if observed > cur_observed:
                replace = True
            elif observed == cur_observed and run_id < cur_run_id:
                replace = True
        if replace:
            best[job] = (attempt, observed, run_id, row)
    return {job: entry[3] for job, entry in best.items()}


