import quotes
import runs
import times

__all__ = ["snapshot"]


def snapshot(quote_rows, run_rows, event, asof):
    """Build the integrated synthetic snapshot.

    Validation of asof and event happens before either input list is
    inspected. Quotes and runs are computed independently by the
    supporting modules.
    """
    as_of = times.instant(asof)
    if not isinstance(event, str) or len(event) == 0:
        raise ValueError("event must be a nonempty string")
    selected_quotes = quotes.select(quote_rows, event, as_of)
    selected_runs = runs.reconcile(run_rows, as_of)
    successful_rows = 0
    failures = []
    partial_jobs = []
    unknown_jobs = []
    for job, row in selected_runs.items():
        status = row.get("status")
        if status == "ok" or status == "partial":
            successful_rows += row.get("downloaded_rows", 0)
        if status == "failed":
            failures.append(job)
        elif status == "partial":
            partial_jobs.append(job)
        elif status == "pending":
            unknown_jobs.append(job)
    return {
        "quotes": selected_quotes,
        "runs": selected_runs,
        "successful_rows": int(successful_rows),
        "failures": sorted(failures),
        "partial_jobs": sorted(partial_jobs),
        "unknown_jobs": sorted(unknown_jobs),
    }"}
